/**
 * POJO representing a job event from the Google cluster-usage trace.
 *
 * Event types (per Google trace format v2.1):
 *   0 SUBMIT, 1 SCHEDULE, 2 EVICT, 3 FAIL, 4 FINISH,
 *   5 KILL, 6 LOST, 7 UPDATE_PENDING, 8 UPDATE_RUNNING.
 */
public class JobEvent {

    public long time;
    public long jobId;
    public int eventType;

    public JobEvent() {}

    public JobEvent(long time, long jobId, int eventType) {
        this.time = time;
        this.jobId = jobId;
        this.eventType = eventType;
    }

    public static JobEvent fromCsvLine(String line) {
        String[] parts = line.split(",", -1);
        if (parts.length < 4) {
            return null;
        }
        try {
            long time = Long.parseLong(parts[0]);
            long jobId = Long.parseLong(parts[2]);
            int eventType = Integer.parseInt(parts[3]);
            return new JobEvent(time, jobId, eventType);
        } catch (NumberFormatException e) {
            return null;
        }
    }

    @Override
    public String toString() {
        return "JobEvent{" + time + "," + jobId + "," + eventType + "}";
    }
}
