{"command": "create", "path": "/app/workspace/src/main/java/clusterdata/sources/TaskEventSource.java", "file_text": "package clusterdata.sources;

import clusterdata.datatypes.TaskEvent;
import org.apache.flink.streaming.api.functions.source.SourceFunction;

import java.io.BufferedReader;
import java.io.FileInputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.zip.GZIPInputStream;

/**
 * Reads a single gzipped task-event CSV file and emits {@link TaskEvent}s
 * in file order.  The Google trace files are already sorted by event time,
 * so downstream watermark strategies may assume monotonic timestamps.
 */
public class TaskEventSource implements SourceFunction<TaskEvent> {

    private static final long serialVersionUID = 1L;

    private final String path;
    private volatile boolean running = true;

    public TaskEventSource(String path) {
        this.path = path;
    }

    @Override
    public void run(SourceContext<TaskEvent> ctx) throws Exception {
        try (FileInputStream fis = new FileInputStream(path);
             GZIPInputStream gis = new GZIPInputStream(fis);
             InputStreamReader isr = new InputStreamReader(gis, StandardCharsets.UTF_8);
             BufferedReader reader = new BufferedReader(isr)) {
            String line;
            while (running && (line = reader.readLine()) != null) {
                TaskEvent e = TaskEvent.fromCsvLine(line);
                if (e != null) {
                    ctx.collect(e);
                }
            }
        }
    }

    @Override
    public void cancel() {
        running = false;
    }
}
