{"command": "create", "path": "/app/workspace/src/main/java/clusterdata/datatypes/TaskEvent.java", "file_text": "package clusterdata.datatypes;

/**
 * POJO representing a task event from the Google cluster-usage trace.
 *
 * Event types (per Google trace format v2.1):
 *   0 SUBMIT, 1 SCHEDULE, 2 EVICT, 3 FAIL, 4 FINISH,
 *   5 KILL, 6 LOST, 7 UPDATE_PENDING, 8 UPDATE_RUNNING.
 */
public class TaskEvent {

    public long time;
    public long jobId;
    public long taskIndex;
    public int eventType;

    public TaskEvent() {}

    public TaskEvent(long time, long jobId, long taskIndex, int eventType) {
        this.time = time;
        this.jobId = jobId;
        this.taskIndex = taskIndex;
        this.eventType = eventType;
    }

    public static TaskEvent fromCsvLine(String line) {
        String[] parts = line.split(",", -1);
        if (parts.length < 6) {
            return null;
        }
        try {
            long time = Long.parseLong(parts[0]);
            long jobId = Long.parseLong(parts[2]);
            long taskIndex = parts[3].isEmpty() ? -1L : Long.parseLong(parts[3]);
            int eventType = Integer.parseInt(parts[5]);
            return new TaskEvent(time, jobId, taskIndex, eventType);
        } catch (NumberFormatException e) {
            return null;
        }
    }

    @Override
    public String toString() {
        return "TaskEvent{" + time + "," + jobId + "," + taskIndex + "," + eventType + "}";
    }
}
