    71	        // Session gap in microseconds (trace timestamps are microseconds).
    72	        final long gapMicros = sesssize * 1_000_000L;
    73	
    74	        // set up streaming execution environment
    75	        StreamExecutionEnvironment env = StreamExecutionEnvironment.getExecutionEnvironment();
    76	        env.setParallelism(1);
    77	
    78	        TypeInformation<Tuple3<Long, Long, Integer>> unifiedTypeInfo =
    79	                TypeInformation.of(new TypeHint<Tuple3<Long, Long, Integer>>() {});
    80	
    81	        // ---------------------------------------------------------------
    82	        // 1. Task SUBMIT events -> (jobId, time, KIND_SUBMIT)
    83	        // ---------------------------------------------------------------
    84	        DataStream<Tuple3<Long, Long, Integer>> submits = env
    85	                .addSource(AppBase.taskSourceOrTest(new TaskEventSource(taskInput)))
    86	                .filter(new FilterFunction<TaskEvent>() {
    87	                    @Override
    88	                    public boolean filter(TaskEvent e) {
    89	                        return e.eventType == TASK_EVENT_SUBMIT;
    90	                    }
    91	                })
    92	                .map(new MapFunction<TaskEvent, Tuple3<Long, Long, Integer>>() {
    93	                    @Override
    94	                    public Tuple3<Long, Long, Integer> map(TaskEvent e) {
    95	                        return Tuple3.of(e.jobId, e.time, KIND_SUBMIT);
    96	                    }
    97	                })
    98	                .returns(unifiedTypeInfo)
    99	                .assignTimestampsAndWatermarks(
   100	                        WatermarkStrategy.<Tuple3<Long, Long, Integer>>forMonotonousTimestamps()
   101	                                .withTimestampAssigner((e, ts) -> e.f1));
   102	
   103	        // ---------------------------------------------------------------
   104	        // 2. Job terminal events (FAIL/FINISH/KILL) -> (jobId, time, KIND_FINISH)
   105	        // ---------------------------------------------------------------
   106	        DataStream<Tuple3<Long, Long, Integer>> finishes = env
   107	                .addSource(AppBase.jobSourceOrTest(new JobEventSource(jobInput)))
   108	                .filter(new FilterFunction<JobEvent>() {
   109	                    @Override
