   128	        // 3. Union, key by jobId, compute longest stage per job
   129	        // ---------------------------------------------------------------
   130	        DataStream<Tuple2<Long, Integer>> results = submits.union(finishes)
   131	                .keyBy(new KeySelector<Tuple3<Long, Long, Integer>, Long>() {
   132	                    @Override
   133	                    public Long getKey(Tuple3<Long, Long, Integer> e) {
   134	                        return e.f0;
   135	                    }
   136	                })
   137	                .process(new LongestStageFn(gapMicros));
