   158	     * largest stage, which is emitted as a {@code (jobId, count)} tuple.
   159	     */
   160	    public static final class LongestStageFn
   161	            extends KeyedProcessFunction<Long, Tuple3<Long, Long, Integer>, Tuple2<Long, Integer>> {
   162	
   163	        private static final long serialVersionUID = 1L;
   164	
   165	        private final long gapMicros;
   166	
   167	        private transient ListState<Long> submitTimes;
   168	        private transient ValueState<Long> finishTime;
   169	
   170	        public LongestStageFn(long gapMicros) {
   171	            this.gapMicros = gapMicros;
   172	        }
   173	
   174	        @Override
   175	        public void open(Configuration cfg) {
   176	            submitTimes = getRuntimeContext().getListState(
   177	                    new ListStateDescriptor<>("submitTimes", Long.class));
   178	            finishTime = getRuntimeContext().getState(
   179	                    new ValueStateDescriptor<>("finishTime", Long.class));
   180	        }
   181	
   182	        @Override
   183	        public void processElement(Tuple3<Long, Long, Integer> e,
   184	                                   Context ctx,
   185	                                   Collector<Tuple2<Long, Integer>> out) throws Exception {
   186	            if (e.f2 == KIND_SUBMIT) {
   187	                submitTimes.add(e.f1);
   188	            } else {
   189	                // Keep the earliest terminal event we see for this job.
   190	                Long existing = finishTime.value();
   191	                if (existing == null || e.f1 < existing) {
   192	                    finishTime.update(e.f1);
   193	                }
   194	                // Fire after watermark has definitely passed the finish time
   195	                // so that every SUBMIT with time <= finishTime is already buffered.
   196	                ctx.timerService().registerEventTimeTimer(e.f1 + 1L);
   197	            }
   198	        }
   199	
   200	        @Override
   201	        public void onTimer(long timestamp,
   202	                            OnTimerContext ctx,
   203	                            Collector<Tuple2<Long, Integer>> out) throws Exception {
   204	            Long ft = finishTime.value();
   205	            if (ft == null) {
   206	                // Already emitted via an earlier timer; nothing to do.
   207	                return;
   208	            }
   209	
   210	            List<Long> times = new ArrayList<>();
   211	            for (Long t : submitTimes.get()) {
   212	                // Only submits up to (and including) the job finish time count
   213	                // as "while the job was running".
   214	                if (t <= ft) {
   215	                    times.add(t);
   216	                }
   217	            }
   218	            Collections.sort(times);
   219	
   220	            int currentStage = 0;
   221	            int maxStage = 0;
   222	            long lastSubmit = Long.MIN_VALUE;
   223	            for (long t : times) {
   224	                if (currentStage == 0 || t - lastSubmit > gapMicros) {
   225	                    if (currentStage > maxStage) {
   226	                        maxStage = currentStage;
   227	                    }
   228	                    currentStage = 1;
   229	                } else {
   230	                    currentStage++;
   231	                }
   232	                lastSubmit = t;
   233	            }
   234	            if (currentStage > maxStage) {
   235	                maxStage = currentStage;
   236	            }
   237	
   238	            out.collect(Tuple2.of(ctx.getCurrentKey(), maxStage));
   239	
   240	            submitTimes.clear();
   241	            finishTime.clear();
   242	        }
   243	    }
   244	}
