    15	import org.apache.flink.api.common.state.ValueStateDescriptor;
    16	import org.apache.flink.api.common.typeinfo.TypeHint;
    17	import org.apache.flink.api.common.typeinfo.TypeInformation;
    18	import org.apache.flink.api.java.functions.KeySelector;
    19	import org.apache.flink.api.java.tuple.Tuple2;
    20	import org.apache.flink.api.java.tuple.Tuple3;
    21	import org.apache.flink.api.java.utils.ParameterTool;
    22	import org.apache.flink.configuration.Configuration;
    23	import org.apache.flink.core.fs.FileSystem;
    24	import org.apache.flink.streaming.api.datastream.DataStream;
    25	import org.apache.flink.streaming.api.environment.StreamExecutionEnvironment;
    26	import org.apache.flink.streaming.api.functions.KeyedProcessFunction;
    27	import org.apache.flink.util.Collector;
    28	
    29	import java.util.ArrayList;
    30	import java.util.Collections;
    31	import java.util.List;
    32	
    33	/**
    34	 * For each job, identify "stages" of task SUBMIT activity and output the number of
    35	 * tasks in the longest stage once the job has finished.
    36	 *
    37	 * A stage is a run of task SUBMIT events (event type 0) for the same jobId where
    38	 * consecutive SUBMITs are separated by less than {@code sesssize} seconds in event
    39	 * time.  Once a job has produced a terminal event (FAIL=3, FINISH=4, KILL=5), the
    40	 * job emits {@code (jobId, max_tasks_in_longest_stage)}.
    41	 *
    42	 * If the same task is submitted, fails/evicted, and resubmitted later, each SUBMIT
    43	 * event contributes to its stage's count independently.
    44	 */
    45	public class LongestSessionPerJob extends AppBase {
    46	
    47	    /** Task-event event-type code for SUBMIT. */
    48	    private static final int TASK_EVENT_SUBMIT = 0;
    49	
    50	    /** Job-event event-type codes that mark the job as "finished". */
    51	    private static final int JOB_EVENT_FAIL = 3;
    52	    private static final int JOB_EVENT_FINISH = 4;
    53	    private static final int JOB_EVENT_KILL = 5;
    54	
    55	    /** Tag used in the unified stream for a task SUBMIT event. */
    56	    private static final int KIND_SUBMIT = 0;
    57	
    58	    /** Tag used in the unified stream for a job terminal event. */
    59	    private static final int KIND_FINISH = 1;
    60	
    61	    public static void main(String[] args) throws Exception {
    62	
    63	        ParameterTool params = ParameterTool.fromArgs(args);
    64	        String taskInput = params.get("task_input", null);
    65	        String jobInput = params.get("job_input", null);
    66	        String outputPath = params.get("output", null);
    67	        System.out.println("task_input  " + taskInput);
    68	        System.out.println("job_input  " + jobInput);
    69	        final int sesssize = params.getInt("sesssize", 600);
    70	
    71	        // Session gap in microseconds (trace timestamps are microseconds).
    72	        final long gapMicros = sesssize * 1_000_000L;
    73	
    74	        // set up streaming execution environment
    75	        StreamExecutionEnvironment env = StreamExecutionEnvironment.getExecutionEnvironment();
    76	        env.setParallelism(1);
    77	
    78	        TypeInformation<Tuple3<Long, Long, Integer>> unifiedTypeInfo =
    79	                TypeInformation.of(new TypeHint<Tuple3<Long, Long, Integer>>() {});
    80	
    81	        // ---------------------------------------------------------------
    82	        // 1. Task SUBMIT events -> (jobId, time, KIND_SUBMIT)
    83	        // ---------------------------------------------------------------
    84	        DataStream<Tuple3<Long, Long, Integer>> submits = env
    85	                .addSource(AppBase.taskSourceOrTest(new TaskEventSource(taskInput)))
    86	                .filter(new FilterFunction<TaskEvent>() {
    87	                    @Override
    88	                    public boolean filter(TaskEvent e) {
    89	                        return e.eventType == TASK_EVENT_SUBMIT;
    90	                    }
    91	                })
    92	                .map(new MapFunction<TaskEvent, Tuple3<Long, Long, Integer>>() {
    93	                    @Override
    94	                    public Tuple3<Long, Long, Integer> map(TaskEvent e) {
    95	                        return Tuple3.of(e.jobId, e.time, KIND_SUBMIT);
    96	                    }
    97	                })
    98	                .returns(unifiedTypeInfo)
    99	                .assignTimestampsAndWatermarks(
   100	                        WatermarkStrategy.<Tuple3<Long, Long, Integer>>forMonotonousTimestamps()
   101	                                .withTimestampAssigner((e, ts) -> e.f1));
   102	
   103	        // ---------------------------------------------------------------
   104	        // 2. Job terminal events (FAIL/FINISH/KILL) -> (jobId, time, KIND_FINISH)
   105	        // ---------------------------------------------------------------
   106	        DataStream<Tuple3<Long, Long, Integer>> finishes = env
   107	                .addSource(AppBase.jobSourceOrTest(new JobEventSource(jobInput)))
   108	                .filter(new FilterFunction<JobEvent>() {
   109	                    @Override
   110	                    public boolean filter(JobEvent e) {
   111	                        return e.eventType == JOB_EVENT_FINISH
   112	                                || e.eventType == JOB_EVENT_FAIL
   113	                                || e.eventType == JOB_EVENT_KILL;
   114	                    }
   115	                })
   116	                .map(new MapFunction<JobEvent, Tuple3<Long, Long, Integer>>() {
   117	                    @Override
   118	                    public Tuple3<Long, Long, Integer> map(JobEvent e) {
   119	                        return Tuple3.of(e.jobId, e.time, KIND_FINISH);
   120	                    }
   121	                })
   122	                .returns(unifiedTypeInfo)
   123	                .assignTimestampsAndWatermarks(
   124	                        WatermarkStrategy.<Tuple3<Long, Long, Integer>>forMonotonousTimestamps()
   125	                                .withTimestampAssigner((e, ts) -> e.f1));
   126	
   127	        // ---------------------------------------------------------------
   128	        // 3. Union, key by jobId, compute longest stage per job
   129	        // ---------------------------------------------------------------
   130	        DataStream<Tuple2<Long, Integer>> results = submits.union(finishes)
   131	                .keyBy(new KeySelector<Tuple3<Long, Long, Integer>, Long>() {
   132	                    @Override
   133	                    public Long getKey(Tuple3<Long, Long, Integer> e) {
   134	                        return e.f0;
   135	                    }
   136	                })
   137	                .process(new LongestStageFn(gapMicros));
   138	
   139	        // ---------------------------------------------------------------
   140	        // 4. Write output
   141	        // ---------------------------------------------------------------
   142	        if (AppBase.out != null) {
   143	            @SuppressWarnings({"unchecked", "rawtypes"})
   144	            org.apache.flink.streaming.api.functions.sink.SinkFunction sink = AppBase.out;
   145	            results.addSink(sink);
   146	        } else {
   147	            results.writeAsText(outputPath, FileSystem.WriteMode.OVERWRITE).setParallelism(1);
   148	        }
   149	
   150	        env.execute("LongestSessionPerJob");
   151	    }
   152	
   153	    /**
   154	     * KeyedProcessFunction that buffers all SUBMIT timestamps for a job and,
   155	     * when a terminal job event arrives, schedules an event-time timer at
   156	     * {@code finishTime + 1}.  When the timer fires (watermark has passed the
   157	     * finish time), the SUBMIT timestamps are sorted and scanned to find the
   158	     * largest stage, which is emitted as a {@code (jobId, count)} tuple.
   159	     */
   160	    public static final class LongestStageFn
   161	            extends KeyedProcessFunction<Long, Tuple3<Long, Long, Integer>, Tuple2<Long, Integer>> {
   162	
   163	        private static final long serialVersionUID = 1L;
   164	
   165	        private final long gapMicros;
   166	
   167	        private transient ListState<Long> submitTimes;
   168	        private transient ValueState<Long> finishTime;
   169	
   170	        public LongestStageFn(long gapMicros) {
   171	            this.gapMicros = gapMicros;
   172	        }
   173	
   174	        @Override
   175	        public void open(Configuration cfg) {
   176	            submitTimes = getRuntimeContext().getListState(
   177	                    new ListStateDescriptor<>("submitTimes", Long.class));
   178	            finishTime = getRuntimeContext().getState(
   179	                    new ValueStateDescriptor<>("finishTime", Long.class));
   180	        }
   181	
   182	        @Override
   183	        public void processElement(Tuple3<Long, Long, Integer> e,
   184	                                   Context ctx,
   185	                                   Collector<Tuple2<Long, Integer>> out) throws Exception {
   186	            if (e.f2 == KIND_SUBMIT) {
   187	                submitTimes.add(e.f1);
   188	            } else {
   189	                // Keep the earliest terminal event we see for this job.
   190	                Long existing = finishTime.value();
   191	                if (existing == null || e.f1 < existing) {
   192	                    finishTime.update(e.f1);
   193	                }
   194	                // Fire after watermark has definitely passed the finish time
   195	                // so that every SUBMIT with time <= finishTime is already buffered.
   196	                ctx.timerService().registerEventTimeTimer(e.f1 + 1L);
   197	            }
   198	        }
   199	
   200	        @Override
   201	        public void onTimer(long timestamp,
   202	                            OnTimerContext ctx,
   203	                            Collector<Tuple2<Long, Integer>> out) throws Exception {
   204	            Long ft = finishTime.value();
   205	            if (ft == null) {
   206	                // Already emitted via an earlier timer; nothing to do.
   207	                return;
   208	            }
   209	
   210	            List<Long> times = new ArrayList<>();
   211	            for (Long t : submitTimes.get()) {
   212	                // Only submits up to (and including) the job finish time count
   213	                // as "while the job was running".
   214	                if (t <= ft) {
   215	                    times.add(t);
   216	                }
   217	            }
   218	            Collections.sort(times);
   219	
   220	            int currentStage = 0;
   221	            int maxStage = 0;
   222	            long lastSubmit = Long.MIN_VALUE;
   223	            for (long t : times) {
   224	                if (currentStage == 0 || t - lastSubmit > gapMicros) {
   225	                    if (currentStage > maxStage) {
   226	                        maxStage = currentStage;
   227	                    }
   228	                    currentStage = 1;
   229	                } else {
   230	                    currentStage++;
   231	                }
   232	                lastSubmit = t;
   233	            }
   234	            if (currentStage > maxStage) {
   235	                maxStage = currentStage;
   236	            }
   237	
   238	            out.collect(Tuple2.of(ctx.getCurrentKey(), maxStage));
   239	
   240	            submitTimes.clear();
   241	            finishTime.clear();
   242	        }
   243	    }
   244	}
